-- Reimporta da zero il catalogo BDA-IEO dalla versione revisionata dei JSON sorgente
-- (wiki/sorgenti/2026-11-19-alimenti-bda-json/): valori corretti e tutti i nutrienti della fonte.
-- Decisione di Andrea (2026-11-19), possibile perché il database non è ancora in produzione:
--   1. elimina tutti i piani alimentari (pasti, esempi, righe, target macro e note vanno in cascata);
--   2. svuota alimenti, compresi gli alimenti personalizzati;
--   3. aggiunge le colonne dei nuovi nutrienti;
--   4. reinserisce i 1109 alimenti BDA.
-- Mappatura come V19: grassi_g = lipidi_g, fibre_g = fibra_g, zuccheri_g = carboidrati_solubili_g.
-- I nuovi nutrienti hanno lo stesso nome della chiave nel JSON. Valori arrotondati a 2 decimali.
-- Generata una tantum da uno script Node fuori dal repo (stessa scelta di V19, ADR 0005).

DELETE FROM piani_alimentari;
DELETE FROM alimenti;

ALTER TABLE alimenti
    ADD COLUMN parte_edibile_percentuale INTEGER,
    ADD COLUMN anno INTEGER,
    ADD COLUMN note TEXT,
    ADD COLUMN kj NUMERIC(9,2),
